style.css:
*{box-sizing:border-box} :root{--bg:#090b11;--panel:#12141d;--panel2:#1b1425;--text:#f7f6fb;--muted:#a7a8bb;--pink:#ff2674;--pink2:#c51a88;--line:#242633}
html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 75% 0%,#1a1026 0,transparent 34%),var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
button,input{font:inherit}button{cursor:pointer;color:inherit}.topbar{height:70px;position:fixed;inset:0 0 auto;z-index:10;display:flex;align-items:center;gap:28px;padding:0 24px;background:rgba(9,11,17,.94);backdrop-filter:blur(16px);border-bottom:1px solid var(--line)}
.brand{font-size:26px;font-weight:850;letter-spacing:-1.1px;text-decoration:none;color:#fff;white-space:nowrap}.brand>span:last-child{color:var(--pink)}.brand-mark{display:inline-grid;place-items:center;width:33px;height:33px;margin-right:5px;border-radius:11px;background:linear-gradient(140deg,#ff5594,#b91d91);color:#fff;font-size:22px;transform:rotate(-8deg)}
.search{display:flex;align-items:center;gap:12px;max-width:480px;width:100%;margin:auto;background:#151720;border:1px solid #282a38;border-radius:13px;padding:0 15px;height:46px;color:#d7d7e4}.search span{font-size:27px}.search input{border:0;outline:0;background:transparent;color:white;width:100%;font-size:14px}.search input::placeholder{color:#9294a8}.top-actions{display:flex;align-items:center;gap:12px}.top-actions button{border:0;background:transparent;white-space:nowrap}.premium{color:#ffc842;font-weight:750}.language{color:#d6d7e5}.btn{border:1px solid transparent;border-radius:12px;padding:12px 22px;font-weight:750;transition:.2s}.btn:hover{transform:translateY(-1px);filter:brightness(1.1)}.btn-ghost{background:#17141f!important;border-color:#34283d!important}.btn-pink{background:linear-gradient(110deg,var(--pink),#df1b80);box-shadow:0 7px 24px #ff267426}.mobile-menu{display:none;background:none;border:0;font-size:23px}
.sidebar{position:fixed;top:70px;bottom:0;left:0;width:216px;padding:14px 12px;border-right:1px solid var(--line);background:#0b0d13;overflow-y:auto;z-index:5}.nav-group{display:grid;gap:5px}.nav-link{display:flex;align-items:center;gap:15px;text-align:left;width:100%;border:0;background:transparent;border-radius:11px;padding:12px 15px;color:#bfc0d2;font-size:15px}.nav-link:first-letter{font-size:20px}.nav-link:hover,.nav-link.active{background:#291324;color:#ff4b8a}.nav-link.active{font-weight:750}.side-heading{font-size:12px;letter-spacing:1px;color:#777b91;margin:25px 13px 12px}.sidebar-note{font-size:11px;line-height:1.6;color:#686b7e;border-top:1px solid var(--line);margin-top:25px;padding:17px 8px}
.main-content{margin-left:216px;padding:83px 22px 28px;max-width:1800px}.hero{min-height:285px;display:grid;grid-template-columns:1fr .95fr;overflow:hidden;border-radius:17px;border:1px solid #2b2034;background:linear-gradient(115deg,#211426,#11121d 60%,#301039);position:relative}.hero-copy{padding:27px 30px;position:relative;z-index:2;align-self:center}.eyebrow{font-size:10px;letter-spacing:2px;color:#ff7aab;font-weight:800}.hero h1{font-size:clamp(33px,3.3vw,52px);line-height:1.02;letter-spacing:-1.8px;margin:13px 0}.hero h1 span{color:var(--pink)}.hero-copy>p:not(.eyebrow){color:#d0cede;line-height:1.6;max-width:370px;margin:12px 0 20px}.hero-art{position:relative;min-height:285px;overflow:hidden;background:radial-gradient(ellipse at 52% 40%,#a93c98 0,#55235e 25%,#21142f 57%,#11121d 80%)}.hero-art:before,.hero-art:after{content:"";position:absolute;border-radius:50%;filter:blur(2px)}.hero-art:before{width:280px;height:280px;background:linear-gradient(145deg,#f04e9c,#672de0);right:12%;top:6%;opacity:.72}.hero-art:after{width:200px;height:200px;background:#ff7cae;right:28%;top:28%;opacity:.38;filter:blur(35px)}.orb{position:absolute;border-radius:50%;z-index:1}.orb-one{width:100px;height:150px;right:30%;top:20%;background:linear-gradient(120deg,#f8a8d3,#4b2e76);transform:rotate(28deg);filter:blur(1px)}.orb-two{width:170px;height:230px;right:10%;top:30%;background:linear-gradient(130deg,#251b46,#d846a7);transform:rotate(-28deg);opacity:.75}.orb-three{width:190px;height:40px;right:5%;bottom:8%;background:#fa3c99;filter:blur(30px)}.hero-glass{position:absolute;z-index:2;right:8%;bottom:20px;border:1px solid #ffffff40;background:#11101c99;backdrop-filter:blur(15px);padding:14px 18px;border-radius:15px;display:grid;gap:7px;box-shadow:0 15px 50px #0005}.hero-glass span{font-size:10px;color:#ff5e9d;font-weight:900}.hero-glass strong{font-size:19px;line-height:1.1}.hero-glass small{color:#c6bfd0}
.section{margin-top:24px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.section-head h2{font-size:20px;letter-spacing:-.5px;margin:0}.pink-icon{color:var(--pink);margin-right:7px}.view-all{border:0;background:transparent;color:#c5c6d7;font-size:13px}.view-all:hover{color:#ff6ca2}.stream-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px}.stream-card{min-width:0;cursor:pointer}.thumb{position:relative;aspect-ratio:1.12/1;overflow:hidden;border-radius:10px;background:linear-gradient(135deg,#39203e,#161a2a);border:1px solid #2c2938}.thumb-art{position:absolute;inset:0;background:radial-gradient(circle at 60% 25%,var(--glow,#c64a94),transparent 35%),linear-gradient(145deg,var(--shade,#492447),#171a27 70%);transition:transform .3s}.thumb-art:before{content:"";position:absolute;width:44%;height:65%;left:30%;top:14%;border-radius:48% 48% 28% 28%;background:linear-gradient(145deg,#ffd4c5,#a76568 70%,#3b243a);box-shadow:0 20px 28px #08071080;transform:rotate(var(--tilt,4deg))}.thumb-art:after{content:"";position:absolute;width:55%;height:28%;left:24%;bottom:-4%;border-radius:50% 50% 0 0;background:linear-gradient(100deg,#17172a,var(--shirt,#e94f88));transform:rotate(-8deg)}.stream-card:hover .thumb-art{transform:scale(1.05)}.live-badge,.viewers{position:absolute;top:9px;z-index:2;border-radius:6px;padding:5px 8px;font-size:11px;font-weight:850}.live-badge{left:8px;background:var(--pink);color:#fff}.viewers{right:7px;background:#090a10c9;color:white}.streamer-meta{padding:8px 8px 0}.name-line{display:flex;align-items:center;gap:5px;font-weight:800;font-size:14px}.verified{display:inline-grid;place-items:center;width:14px;height:14px;border-radius:50%;background:#39a4ff;color:white;font-size:9px}.flag{margin-left:auto;font-size:17px}.bio{font-size:12px;color:#c2c2d2;margin-top:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tags{display:flex;gap:6px;margin-top:9px;flex-wrap:wrap}.tag{background:#222430;border-radius:7px;padding:5px 8px;font-size:10px;color:#e0dfeb}.people-row{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:14px}.person{text-align:center;min-width:0;cursor:pointer}.avatar{width:76px;height:76px;margin:0 auto 7px;border-radius:50%;padding:3px;border:2px solid var(--pink);background:linear-gradient(145deg,#ff4187,#6327ac);position:relative}.avatar-face{height:100%;border-radius:50%;background:radial-gradient(circle at 52% 32%,#f6c5b7 0 20%,#764a57 21% 36%,#191727 37% 70%,#b3317d 71%);}.online-dot{position:absolute;right:0;bottom:0;width:13px;height:13px;background:#5ce26e;border:2px solid var(--bg);border-radius:50%}.person strong{display:block;font-size:12px}.person small{display:block;color:#a3a5b9;font-size:11px;margin-top:4px}.empty-state{grid-column:1/-1;padding:30px;text-align:center;color:var(--muted);border:1px dashed #343342;border-radius:12px}footer{padding:28px 0 5px;color:#666a7d;font-size:11px}
.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;background:#24202e;border:1px solid #45364d;padding:12px 18px;border-radius:12px;z-index:30;transition:.25s;box-shadow:0 10px 35px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}dialog{border:1px solid #383043;border-radius:18px;background:#11121b;color:var(--text);padding:0;width:min(420px,calc(100% - 30px));box-shadow:0 25px 100px #000a}dialog::backdrop{background:#03030acc;backdrop-filter:blur(5px)}.modal-card{padding:27px;display:grid;gap:14px;position:relative}.modal-close{position:absolute;right:16px;top:12px;border:0;background:transparent;font-size:26px;color:#aaa}.modal-brand{font-size:22px}.modal-brand .brand-mark{width:27px;height:27px;font-size:17px}.modal-card h2{margin:8px 0 0}.muted{color:var(--muted);font-size:12px;line-height:1.5}.modal-card label{display:grid;gap:7px;font-size:12px;color:#c9c9d8}.modal-card input{background:#1a1b26;color:white;border:1px solid #343443;border-radius:9px;padding:12px;outline:none}.modal-card input:focus{border-color:var(--pink)}.full-width{width:100%}
@media(max-width:1250px){.stream-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.topbar{gap:16px}.search{max-width:360px}.people-row{grid-template-columns:repeat(8,minmax(0,1fr))}.sidebar{width:190px}.main-content{margin-left:190px}}
@media(max-width:900px){.topbar{padding:0 15px}.brand{font-size:22px}.search{max-width:none}.top-actions .premium,.top-actions .language{display:none}.sidebar{transform:translateX(-105%);transition:transform .25s;width:230px;box-shadow:15px 0 35px #0005}.sidebar.open{transform:translateX(0)}.mobile-menu{display:block}.main-content{margin-left:0;padding:82px 15px 25px}.hero{grid-template-columns:1fr .7fr}.people-row{grid-template-columns:repeat(4,minmax(0,1fr));row-gap:18px}}
@media(max-width:600px){.topbar{height:62px;gap:10px}.brand{font-size:0}.brand-mark{font-size:22px}.search{height:39px;padding:0 9px;gap:5px}.search span{font-size:22px}.search input{font-size:12px}.top-actions{gap:6px}.top-actions .btn{padding:10px 11px;font-size:12px}.top-actions .btn-ghost{display:none}.mobile-menu{font-size:20px;padding:0}.main-content{padding-top:74px}.hero{grid-template-columns:1fr;min-height:0}.hero-copy{padding:23px}.hero h1{font-size:38px}.hero-art{min-height:115px}.hero-glass{right:12px;bottom:10px;padding:8px 12px}.hero-glass strong{font-size:14px}.hero-glass small{font-size:10px}.orb-one{top:-20px}.section-head h2{font-size:17px}.stream-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.people-row{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px 6px}.avatar{width:58px;height:58px}.streamer-meta{padding-left:3px;padding-right:3px}.name-line{font-size:13px}.tags{gap:4px}.tag{font-size:9px;padding:4px 6px}.bio{font-size:11px}.section{margin-top:21px}}
